document.addEventListener("DOMContentLoaded",async()=>{const status=document.getElementById("access-status");try{const user=await window.ApiClient.requireAuthenticatedPage();if(!user)return;if(user.role!=="admin")throw new Error("Chỉ quản trị viên được truy cập trang API Keys.");const response=await window.ApiClient.apiFetch("/api/admin/api-keys/page",{cache:"no-store"},0);if(!response.ok)throw new Error(response.status===403?"Chỉ quản trị viên được truy cập trang API Keys.":"Không thể tải trang. Hãy thử lại.");const html=await response.text();document.open(),document.write(html),document.close()}catch(error){status.textContent=error.message,status.setAttribute("aria-busy","false")}});
